                  reset,
  output          port_group_ready,
  input           port_group_valid,
  input  [7:0]    port_group_bits_opcode,
                  port_group_bits_sliceMask,
  input  [31:0]   port_group_bits_tag,
  output          port_step_ready,
  input           port_step_valid,
  input  [255:0]  port_step_bits_a,
  input  [4095:0] port_step_bits_b,
  input  [2:0]    port_step_bits_context,
  input           port_step_bits_clear,
                  port_step_bits_last,
                  port_step_bits_finish,
                  port_step_bits_emit,
                  port_result_ready,
  output          port_result_valid,
  output [8191:0] port_result_bits_data_0,
                  port_result_bits_data_1,
                  port_result_bits_data_2,
                  port_result_bits_data_3,
                  port_result_bits_data_4,
                  port_result_bits_data_5,
                  port_result_bits_data_6,
                  port_result_bits_data_7,
                  port_result_bits_data_8,
                  port_result_bits_data_9,
                  port_result_bits_data_10,
                  port_result_bits_data_11,
                  port_result_bits_data_12,
                  port_result_bits_data_13,
                  port_result_bits_data_14,
                  port_result_bits_data_15,
  output [2:0]    port_result_bits_context,
  output          port_result_bits_last,
                  port_result_bits_error,
  input           port_done_ready,
  output          port_done_valid,
  output [31:0]   port_done_bits_tag,
  output          port_done_bits_error,
  input           port_abort,
  output [63:0]   port_acceptedSteps,
                  port_wideSteps,
  output          port_resetRequired,
  input  [15:0]   a_a,
                  a_b,
  input  [31:0]   a_c,
  output [23:0]   a_mulAddA,
                  a_mulAddB,
  output [47:0]   a_mulAddC,
  output [53:0]   a_meta,
  input  [23:0]   b_mulAddA,
                  b_mulAddB,
  input  [47:0]   b_mulAddC,
  output [48:0]   b_mulAddResult,
  input  [53:0]   c_meta,
  input  [48:0]   c_mulAddResult,
  output [40:0]   c_raw,
  output          c_invalid,
  input  [40:0]   d_raw,
  input           d_invalid,
  output [31:0]   d_out,
  output [4:0]    d_exceptionFlags
);

  MatrixPipelineProbe top (
    .clock                   (clock),
    .reset                   (reset),
    .io_group_ready          (port_group_ready),
    .io_group_valid          (port_group_valid),
    .io_group_bits_opcode    (port_group_bits_opcode),
    .io_group_bits_sliceMask (port_group_bits_sliceMask),
    .io_group_bits_tag       (port_group_bits_tag),
    .io_step_ready           (port_step_ready),
    .io_step_valid           (port_step_valid),
    .io_step_bits_a          (port_step_bits_a),
    .io_step_bits_b          (port_step_bits_b),
    .io_step_bits_context    (port_step_bits_context),
    .io_step_bits_clear      (port_step_bits_clear),
    .io_step_bits_last       (port_step_bits_last),
    .io_step_bits_finish     (port_step_bits_finish),
    .io_step_bits_emit       (port_step_bits_emit),
    .io_result_ready         (port_result_ready),
    .io_result_valid         (port_result_valid),
    .io_result_bits_data_0   (port_result_bits_data_0),
    .io_result_bits_data_1   (port_result_bits_data_1),
    .io_result_bits_data_2   (port_result_bits_data_2),
    .io_result_bits_data_3   (port_result_bits_data_3),
    .io_result_bits_data_4   (port_result_bits_data_4),
    .io_result_bits_data_5   (port_result_bits_data_5),
    .io_result_bits_data_6   (port_result_bits_data_6),
    .io_result_bits_data_7   (port_result_bits_data_7),
    .io_result_bits_data_8   (port_result_bits_data_8),
    .io_result_bits_data_9   (port_result_bits_data_9),
    .io_result_bits_data_10  (port_result_bits_data_10),
    .io_result_bits_data_11  (port_result_bits_data_11),
    .io_result_bits_data_12  (port_result_bits_data_12),
    .io_result_bits_data_13  (port_result_bits_data_13),
    .io_result_bits_data_14  (port_result_bits_data_14),
    .io_result_bits_data_15  (port_result_bits_data_15),
    .io_result_bits_context  (port_result_bits_context),
    .io_result_bits_last     (port_result_bits_last),
    .io_result_bits_error    (port_result_bits_error),
    .io_done_ready           (port_done_ready),
    .io_done_valid           (port_done_valid),
    .io_done_bits_tag        (port_done_bits_tag),
    .io_done_bits_error      (port_done_bits_error),
    .io_abort                (port_abort),
    .io_acceptedSteps        (port_acceptedSteps),
    .io_wideSteps            (port_wideSteps),
    .io_resetRequired        (port_resetRequired)
  );
  HeteroBF16FmaPre pre (
    .io_a       (a_a),
    .io_b       (a_b),
    .io_c       (a_c),
    .io_mulAddA (a_mulAddA),
    .io_mulAddB (a_mulAddB),
    .io_mulAddC (a_mulAddC),
    .io_meta    (a_meta)
  );
  HeteroBF16FmaMul mul (
    .io_mulAddA      (b_mulAddA),
    .io_mulAddB      (b_mulAddB),
    .io_mulAddC      (b_mulAddC),
    .io_mulAddResult (b_mulAddResult)
  );
  HeteroBF16FmaPost post (
    .io_meta         (c_meta),
    .io_mulAddResult (c_mulAddResult),
    .io_raw          (c_raw),
    .io_invalid      (c_invalid)
  );
  HeteroBF16FmaRound round (
    .io_raw            (d_raw),
    .io_invalid        (d_invalid),
    .io_out            (d_out),
    .io_exceptionFlags (d_exceptionFlags)
  );
endmodule

